SELECT COUNT(*) FROM singer;
SELECT COUNT(*) AS total_number_of_musicians FROM singer;
SELECT Name, Nationality, Age FROM singer ORDER BY Age DESC LIMIT 100;
SELECT Name, Country, Age FROM singer ORDER BY Age DESC;
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer;
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer;
SELECT singer.Name, singer.Age AS youngest_vocalist_age FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID ORDER BY singer.Age ASC LIMIT 1;
SELECT DISTINCT s.Name, c.Year AS publish_year FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID JOIN singer_in_concert sc ON c.concert_ID = sc.concert_ID WHERE s.Age < (SELECT Age FROM singer WHERE Age = (SELECT MAX(Age) FROM singer))
SELECT DISTINCT Country FROM singer WHERE Age > 20;
SELECT DISTINCT s.Country, c.Year FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID WHERE c.Age > 20;
SELECT State, COUNT(singer_in_concert.Singer_ID) AS num_vocalists FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN stadium ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY State
SELECT DISTINCT State, COUNT(*) AS Total_Musicians FROM singer_in_concert JOIN singer ON singer_in_concert.Singer_ID = singer.Singer_ID GROUP BY State;
SELECT singer.Name, singer.Age, singer.Country, singer_in_concert.Song_Name FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID WHERE singer_in_concert.concert_ID IN (SELECT concert_ID FROM concert) AND singer.Age > (SELECT AVG(Age) FROM stadium) ORDER BY singer.Age DESC
SELECT s.Name, c.Concert_Name FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID JOIN stadium st ON c.Stadium_ID = st.Stadium_ID WHERE s.Age > (SELECT AVG(Age) FROM singer)
SELECT stadium.Stadium_ID, singer.Name, concert.Theme FROM concert INNER JOIN singer ON concert.Singer_ID = singer.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year >= 2020 AND concert.Year <= 2025;
SELECT s.Name, c.Stadium_ID FROM concert c JOIN singer_in_concert s ON c.concert_ID = s.concert_ID WHERE c.Year BETWEEN 2020 AND 2025 AND s.Is_male = 'Yes' AND c.Capacity BETWEEN 5000 AND 10000;
SELECT AVG(Capacity), MAX(Capacity) FROM stadium;
SELECT AVG(Capacity), MAX(Capacity) FROM stadium;
SELECT Name, Capacity FROM stadium WHERE Average = (SELECT AVG(Average) FROM stadium ORDER BY Average DESC LIMIT 1)
SELECT Name, Capacity FROM stadium WHERE Highest = (SELECT MAX(Average) FROM stadium)
SELECT COUNT(*) FROM concert WHERE Year IN ('2014', '2015')
SELECT COUNT(*) FROM concert WHERE Year IN ('2014', '2015')
SELECT stadium.Name, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM stadium INNER JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.Stadium_ID GROUP BY stadium.Name
SELECT COUNT(*) AS Shows_Played_per_Stadium FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Stadium_ID
SELECT concert.Name, COUNT(singer_in_concert.Singer_ID) AS show_count FROM concert INNER JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Name HAVING concert.Year >= 2014
SELECT Name, COUNT(Singer_ID) AS show_count FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID GROUP BY Name HAVING COUNT(Singer_ID) > 0 AND Year > 2013;
SELECT concert.Year, COUNT(singer_in_concert.Singer_ID) AS Total_Show FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID JOIN singer ON singer_in_concert.Singer_ID = singer.Singer_ID GROUP BY concert.Year ORDER BY Total_Show DESC LIMIT 1
SELECT concert.Year, singer_in_concert.Singer_ID, singer.Name, singer.Age, concert.Theme FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID JOIN singer ON singer.Singer_ID = singer_in_concert.Singer_ID GROUP BY concert.Year, singer_in_concert.Singer_ID, singer.Name, singer.Age, concert.Theme ORDER BY concert.Year DESC;
SELECT Name FROM stadium WHERE Highest IS NULL OR Lowest IS NULL OR Average IS NULL
SELECT Name FROM stadium WHERE Highest IS NULL OR Lowest IS NULL OR Average IS NULL;
SELECT singer.Country, singer_in_concert.Singer_ID FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID WHERE singer.Age > 40 OR singer.Age < 30;
SELECT Name FROM stadium WHERE Year != 2014
SELECT DISTINCT Name FROM stadium WHERE Year = 2014 AND Highest IS NULL OR Lowest IS NULL
SELECT singer.Name, singer.theme, singer_in_concert.Singer_ID AS singer_id FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID GROUP BY singer.Singer_ID
SELECT singer.Name, concert.Theme, singer_in_concert.Singer_ID AS Singer_ID FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID;
SELECT singer.Name, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID GROUP BY singer.Name
SELECT singer.Name, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID GROUP BY singer.Name
SELECT singer.Name FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year = '2014'
SELECT DISTINCT singer.Name FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year = 2014;
SELECT singer.Name, singer.Country AS Nation FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Theme LIKE '%Hey%'
SELECT singer.Name, singer.Country, singer.Instrument FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE concert.Theme LIKE '%Hey%'
SELECT s.Name, c.Year FROM stadium s JOIN concert c ON s.Stadium_ID = c.Stadium_ID WHERE c.Year IN (2014, 2015)
SELECT s.Name, c.Location FROM stadium s JOIN concert c ON s.Stadium_ID = c.Stadium_ID WHERE c.Year IN (2014, 2015)
