SELECT c.Maker, c.Country, COUNT(c.Model) AS model_count FROM car_makers c JOIN car_names ON c.Maker = car_names.Make JOIN model_list ON c.Maker = model_list.Model GROUP BY c.Maker;
SELECT car_makers.FullName, car_makers.Id, model_list.Model, model_list.Maker, model_list.ModelCount FROM car_makers JOIN model_list ON car_makers.Id = model_list.Maker;
SELECT model_list.ModelId FROM model_list JOIN car_names ON model_list.Model = car_names.Model JOIN car_makers ON car_makers.Id = car_names.MakeId JOIN countries ON car_makers.CountryId = countries.CountryId JOIN continents ON countries.Continent = continents.ContId;
SELECT model_list.ModelId FROM model_list JOIN car_makers ON car_makers.Id = model_list.Maker JOIN car_names ON car_names.MakeId = car_makers.Id JOIN countries ON countries.CountryId = car_makers.CountryId JOIN continents ON continents.ContId = countries.ContinentId WHERE model_list.MPG = (SELECT MIN(MPG) FROM cars_data)
