SELECT c.Maker, c.Year FROM car_makers c JOIN model_list m ON c.Maker = m.Maker JOIN car_names cn ON m.Model = cn.Model JOIN cars_data cd ON cn.MakeId = cd.MakeId WHERE c.Year = (SELECT MIN(c.Year) FROM car_makers c)
