SELECT DISTINCT model_list.Model, model_list.Maker FROM model_list JOIN car_makers ON car_makers.Id = model_list.Maker JOIN car_names ON car_names.MakeId = model_list.Maker JOIN countries ON countries.CountryId = car_makers.CountryId WHERE Year > 1980;
