SELECT CountryName FROM countries JOIN car_makers ON countries.CountryId = car_makers.CountryId GROUP BY CountryName ORDER BY COUNT(CountryName) DESC;
SELECT car_makers.FullName FROM car_makers WHERE car_makers.Maker IN (SELECT car_makers.Maker FROM car_makers JOIN model_list ON car_makers.Id = model_list.Maker GROUP BY car_makers.Maker ORDER BY car_makers.Maker ASC LIMIT 1)
SELECT COUNT(DISTINCT manufacturer_full_name), manufacturer_full_name FROM car_makers JOIN countries ON car_makers.Country = countries.CountryName JOIN car_makers ON car_makers.Maker = car_makers.Maker GROUP BY car_makers.Maker;
