SELECT player_id FROM players JOIN matches ON players.player_id = matches.winner_id WHERE matches.round = '2023' AND matches.minutes > 500000;
SELECT country_code FROM players JOIN matches ON players.player_id = matches.winner_id WHERE matches.round = 1 AND matches.round_points > 50;
SELECT COUNT(DISTINCT rankings.ranking) AS total_trips FROM rankings INNER JOIN matches ON rankings.player_id = matches.loser_id;
SELECT COUNT(DISTINCT rankings.ranking), rankings.ranking FROM rankings JOIN players ON rankings.player_id = players.player_id
SELECT year, COUNT(*) AS num_games FROM matches GROUP BY year;
SELECT year, COUNT(*) AS total_games FROM matches GROUP BY year;
SELECT players.first_name, players.rankings.ranking FROM players INNER JOIN rankings ON players.player_id = rankings.player_id WHERE rankings.ranking = (SELECT MIN(ranking) FROM rankings ORDER BY ranking LIMIT 3)
SELECT p.first_name, p.last_name, r.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking ASC LIMIT 3;
SELECT COUNT(DISTINCT players.player_id) FROM players JOIN matches ON matches.winner_id = players.player_id AND matches.loser_id = players.player_id;
SELECT COUNT(*) FROM players p JOIN matches m ON p.player_id = m.winner_id WHERE p.hand = 'left' AND m.tourney_name = 'WTA Championships'
SELECT p.first_name, p.last_name, m.rank_points AS rank_points FROM players p INNER JOIN matches m ON p.player_id = m.winner_id ORDER BY m.rank_points DESC;
SELECT p.first_name, p.country_code, m.winner_rank_points AS winner_rank_points FROM players p JOIN matches m ON p.player_id = m.winner_id ORDER BY winner_rank_points DESC LIMIT 1;
SELECT COUNT(*) AS participants FROM players;
SELECT players.hand, COUNT(players.hand) AS total_participants FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.hand
SELECT COUNT(DISTINCT ship.id) FROM ship WHERE ship.disposition_of_ship = 'Captured'
SELECT name, tonnage FROM ship ORDER BY name ASC LIMIT 100;
SELECT battle.name, battle.date, battle.result FROM battle JOIN ship ON battle.id = ship.lost_in_battle;
SELECT MAX(killed), MIN(killed) FROM death;
SELECT AVG(death.injured) AS average_injuries_per_time FROM battle JOIN ship ON battle.id = ship.lost_in_battle;
SELECT death.note, death.killed, death.injured FROM death JOIN ship ON death.caused_by_ship_id = ship.id JOIN battle ON ship.lost_in_battle = battle.id WHERE ship.tonnage = 't'
SELECT battle.name, battle.result FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE battle.bulgarian_commander != 'Boril'
SELECT b.id, b.name, s.name, d.note FROM battle b JOIN ship s ON b.id = s.lost_in_battle JOIN death d ON s.id = d.caused_by_ship_id WHERE d.note LIKE '%Brig%'
SELECT battle.id, name, death.killed, death.injured FROM battle INNER JOIN death ON battle.id = death.caused_by_ship_id WHERE death.killed > 10 OR death.injured > 10;
SELECT ship.id, ship.name, battle.id, battle.name FROM ship JOIN battle ON ship.id = battle.id JOIN death ON ship.id = death.caused_by_ship_id GROUP BY ship.id, ship.name ORDER BY battle.id ASC
SELECT DISTINCT name FROM battle JOIN ship ON battle.id = ship.lost_in_battle JOIN death ON ship.id = death.caused_by_ship WHERE bulgarian_commander = 'Kaloyan' AND latin_commander = 'Baldwin I';
SELECT COUNT(DISTINCT battle.name) FROM battle;
SELECT COUNT(*) AS total_combats FROM battle JOIN ship ON ship.id = battle.lost_in_battle WHERE ship.tonnage = '225' AND result = 'lost'
SELECT battle.name, battle.date, ship.name, ship.tonnage, ship.ship_type, ship.location, ship.disposition_of_ship FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship.name = 'Lettice' OR ship.name = 'HMS Atalanta';
SELECT battle.name, battle.result, battle.bulgarian_commander FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship.location = 'English Channel' AND battle.result = 'No vessels lost'
SELECT note FROM death WHERE date LIKE '%East%'
SELECT Addresses.address_id, Addresses.line_1, Addresses.line_2 FROM Addresses WHERE Addresses.line_1 OR Addresses.line_2;
SELECT line_1, line_2 FROM Addresses ORDER BY line_1, line_2 LIMIT 2
SELECT COUNT(*) FROM Courses;
SELECT COUNT(*) FROM Courses;
SELECT course_description FROM Courses;
SELECT course_description, course_name, other_details FROM Courses ORDER BY course_name;
SELECT Addresses.zip_postcode FROM Addresses WHERE Addresses.city = 'Port Chelsea'
SELECT zip_postcode FROM Addresses WHERE city = 'Port Chelsea';
SELECT d.department_name, d.department_id FROM Departments d JOIN Degree_Programs d2 ON d.department_id = d2.department_id ORDER BY d.department_id DESC LIMIT 1;
SELECT D.department_name, COUNT(S.section_name) AS total_degrees_per_section FROM Departments D JOIN Sections S ON D.department_id = S.department_id GROUP BY D.department_id ORDER BY total_degrees_per_section DESC;
SELECT COUNT(DISTINCT department_id) FROM Departments;
SELECT COUNT(DISTINCT department_name) FROM Departments;
SELECT DISTINCT COUNT(DISTINCT course_name) AS course_name_count FROM Courses;
SELECT COUNT(DISTINCT course_name) FROM Courses;
SELECT COUNT(*) FROM Departments WHERE department_name = 'Engineering Division';
SELECT COUNT(*) FROM Departments;
SELECT course_name, section_description FROM Sections JOIN Courses ON Sections.course_id = Courses.course_id;
SELECT course_name, section_description FROM Sections JOIN Courses ON Sections.course_id = Courses.course_id;
SELECT course_name, course_id FROM Courses JOIN Sections ON Sections.course_id = Courses.course_id WHERE Sections.section_description LIKE '%2%'
SELECT course_name, course_id FROM Courses INNER JOIN Sections ON Sections.course_id = Courses.course_id WHERE Sections.section_description LIKE '%less than 2%'
SELECT section_name FROM Sections ORDER BY section_name DESC;
SELECT section_name FROM Sections ORDER BY section_name DESC;
SELECT S.first_name, S.student_id FROM Students S JOIN Student_Enrolment_Courses SC ON S.student_id = SC.student_enrolment_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S1 ON C.course_id = S1.section_id JOIN Departments D ON C.department_id = D.department_id JOIN Degree_Programs DP ON C.department_id = DP.department_id JOIN Semesters S2 ON C.semester_id = S2.semester_id WHERE S.first_name = (SELECT MAX(first_name) FROM Students) ORDER BY S.first_name;
SELECT s.semester_name, s.student_id, s.first_name, s.middle_name, s.last_name FROM Semesters s JOIN Students student ON s.semester_id = student.semester_id JOIN Student_Enrolment_Courses course_enrolment ON student.student_id = course_enrolment.student_course_id JOIN Courses course ON course_enrolment.course_id = course.course_id JOIN Departments department ON course.department_id = department.department_id JOIN Degree_Programs degree_program ON course.department_id = degree_program.department_id WHERE s.semester_name = (SELECT semester_name FROM Semesters ORDER BY semester_name DESC LIMIT 1) AND s.student_id = (SELECT student_id FROM Students ORDER BY semester_name DESC LIMIT 1) ORDER BY s.semester_name DESC;
SELECT course_description, course_name FROM Courses WHERE course_name LIKE '%computer%'
SELECT DISTINCT D.department_name AS department, D.degree_program_id AS degree_program_id, D.degree_summary_name AS degree_summary_name, D.degree_summary_description AS degree_summary_description FROM Departments D JOIN Degree_Programs ON D.department_id = Degree_Programs.department_id WHERE D.department_name LIKE '%computer%';
SELECT s.first_name, s.middle_name, s.last_name, s.id FROM Students s JOIN Student_Enrolment_Courses sc ON s.id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Degree_Programs dp ON ssec.degree_program_id = dp.degree_program_id JOIN Departments d ON dp.department_id = d.department_id;
SELECT S.first_name, S.middle_name, S.last_name, S.student_id, D.department_id, D.department_name FROM Students S JOIN Degree_Programs D ON S.student_id = D.degree_program_id WHERE D.department_id IN (SELECT department_id FROM Departments) AND D.degree_program_id IN (SELECT degree_program_id FROM Degree_Programs) AND D.degree_summary_name = '2 degree programs' ORDER BY S.first_name, S.middle_name, S.last_name;
SELECT S.first_name, S.middle_name, S.last_name FROM Students S;
SELECT s.middle_name, s.family_name, s.first_name FROM Students s;
SELECT DISTINCT D.degree_summary_name, COUNT(D.degree_program_id) AS count FROM Degree_Programs D GROUP BY D.degree_summary_name;
SELECT DISTINCT Degree_Programs.degree_summary_name, COUNT(CASE WHEN Student_Enrolment_Courses.course_id IN (SELECT course_id FROM Student_Enrolment_Courses) AND Student_Enrolment_Courses.student_enrolment_id = Student_Enrolment.student_enrolment_id END) AS total_students FROM Degree_Programs INNER JOIN Student_Enrolment_Courses ON Degree_Programs.degree_program_id = Student_Enrolment_Courses.course_id INNER JOIN Student_Enrolment ON Student_Enrolment_Courses.student_enrolment_id = Student_Enrolment.student_id GROUP BY Degree_Programs.degree_summary_name ORDER BY total_students DESC;
SELECT D.degree_program_id, S.first_name, S.last_name, D.degree_summary_name, D.degree_summary_description FROM Degree_Programs D JOIN Students S ON D.department_id = S.department_id JOIN Sections S ON D.department_id = S.department_id JOIN Courses C ON D.degree_program_id = C.course_id JOIN Sections S ON D.department_id = S.department_id JOIN Students S ON D.department_id = S.department_id;
SELECT D.Degree_Program_id, D.degree_summary_name, D.degree_summary_description FROM Degree_Programs D WHERE D.degree_program_id IN (SELECT D2.degree_program_id FROM Degree_Programs D2 JOIN Students_Enrolment_Courses ON D2.degree_program_id = D.degree_program_id JOIN Student_Enrolment ON D2.degree_program_id = D.degree_program_id GROUP BY D.degree_program_id HAVING COUNT(D2.student_id) = (SELECT COUNT(*) FROM Student_Enrolment_Courses))
SELECT s.id, s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left, s.student_enrolment_count, s.student_enrolment_undergraduate_id FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Degree_Programs dp ON ssec.degree_program_id = dp.degree_program_id GROUP BY s.id ORDER BY s.date_first_registered DESC;
SELECT s.middle_name, s.id, COUNT(CASE WHEN s.student_id = DE.student_id END) AS enrollments, s.first_name, s.last_name FROM Students s JOIN Degree_Programs d ON s.student_id = d.degree_program_id JOIN Semesters s2 ON s.student_id = s2.semester_id JOIN Courses c ON s.student_id = c.course_id JOIN Sections s3 ON s.student_id = s3.section_id JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c2 ON sc.course_id = c2.course_id JOIN Transcripts t ON sc.transcript_id = t.transcript_id JOIN Transcripts_Contents tc ON sc.transcript_id = tc.transcript_id GROUP BY s.middle_name, s.id, s.first_name, s.last_name ORDER BY enrollments DESC;
SELECT section_name FROM Sections WHERE section_description IS NULL;
SELECT DISTINCT student_name FROM Students WHERE date_left IS NULL;
SELECT course_name FROM Courses JOIN Student_Enrolment_Courses ON Courses.course_id = Student_Enrolment_Courses.course_id JOIN Students ON Student_Enrolment_Courses.student_enrolment_id = Students.student_id JOIN Departments ON Student_Enrolment_Courses.student_enrolment_id = Student_Enrolment_Courses.student_enrolment_id JOIN Degree_Programs ON Student_Enrolment_Courses.student_enrolment_id = Degree_Programs.degree_program_id JOIN Semesters ON Student_Enrolment_Courses.student_enrolment_id = Semesters.semester_id;
SELECT course_name FROM Courses C INNER JOIN Students S ON C.course_id = S.current_address_id;
SELECT course_name FROM Courses C JOIN Student_Enrolment_Courses SC ON C.course_id = SC.course_id JOIN Sections S ON C.course_id = S.course_id JOIN Semester_Courses SC_S ON S.semester_id = SC_S.semester_id JOIN Degree_Programs D ON D.degree_program_id = SC_S.degree_program_id GROUP BY course_name ORDER BY COUNT(*) DESC LIMIT 1;
