SELECT s.last_name, s.cell_mobile_number FROM Students s WHERE s.last_name = 'Timmothy' AND s.middle_name = 'Ward';
SELECT student_id, first_name, last_name, cell_mobile_number FROM Students WHERE first_name = 'Timothy' AND last_name = 'Ward';
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered FROM Students s WHERE s.date_first_registered IS NOT NULL ORDER BY s.date_first_registered ASC LIMIT 1;
SELECT s.middle_name, s.first_name, s.last_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id;
SELECT s.last_name, s.middle_name, s.first_name, s.student_id, s.date_first_registered, s.date_left, s.other_student_details FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Departments d ON ssec.degree_program_id = d.department_id JOIN Degree_Programs dp ON d.department_id = dp.department_id JOIN Transcripts t ON ssec.student_id = t.student_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id JOIN Courses c ON tc.student_course_id = c.course_id JOIN Student_Enrolment_Courses sc ON tc.student_course_id = sc.student_course_id WHERE s.date_first_registered < s.date_left AND s.date_first_registered IS NOT NULL;
SELECT s.middle_name, s.family_name, s.first_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id JOIN Transcripts t ON s.student_id = t.transcript_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id JOIN Sections s2 ON s2.section_name = tc.student_course_id JOIN Courses c ON s2.course_id = c.course_id JOIN Departments d ON s2.department_id = d.department_id JOIN Degree_Programs dp ON s2.degree_program_id = dp.degree_program_id;
SELECT s.first_name, s.permanent_address_id, s.permanent_address.line_1, s.permanent_address.line_2, s.permanent_address.line_3, s.permanent_address.city, s.permanent_address.zip_postcode, s.permanent_address.state_province_county, s.first_name, s.permanent_address.other_address_details FROM Students s JOIN Addresses ON s.permanent_address_id = Addresses.address_id WHERE s.permanent_address_id != s.current_address_id;
SELECT s.first_name, s.last_name FROM Students s JOIN Addresses a ON s.permanent_address_id = a.address_id WHERE a.line_3 IS NOT NULL AND a.line_1 != s.last_name;
SELECT s.place_id, s.lines FROM Addresses s JOIN Students student ON s.address_id = student.current_address_id;
SELECT address_id, line_1, line_2 FROM Addresses WHERE line_1 AND line_2 ORDER BY line_1 + line_2 DESC LIMIT 1;
SELECT AVG(transcript_date) AS average_date FROM Transcripts;
SELECT AVG(date_left) AS average_student_record_date FROM Students;
SELECT s.date_left, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections s_sec ON s.section_id = s_sec.section_id JOIN Semesters s_sem ON s_sec.semester_id = s_sem.semester_id JOIN Departments d ON s_sec.degree_program_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON s_sec.transcript_id = t.transcript_id JOIN Transcript_Contents tc ON tc.student_course_id = s_sec.student_course_id WHERE s.date_left IS NOT NULL;
SELECT MIN(transcript_date) AS earliest_date, MAX(transcript_date) AS latest_date FROM Transcripts;
SELECT COUNT(*) FROM Addresses;
SELECT COUNT(*) FROM Students;
SELECT MAX(transcript_date) FROM Transcripts;
SELECT MAX(transcript_date) AS last_student_record_release_date FROM Transcripts;
SELECT MAX(CURRICULUM_ENROLLMENT_ID), COUNT(*) AS ENROLLMENT_COUNT FROM Student_Enrolment_Courses JOIN Student_Enrolment ON Student_Enrolment_Courses.student_enrolment_id = Student_Enrolment.student_id GROUP BY Student_Enrolment_Courses.CURRICULUM_ENROLLMENT_ID;
SELECT MAX(Course_id), MAX(Curriculum) FROM Courses JOIN Degree_Programs ON Courses.course_id = Degree_Programs.degree_program_id GROUP BY Course_id;
SELECT student_id, date_first_registered, date_left FROM Students WHERE date_left IS NULL ORDER BY date_first_registered ASC LIMIT 1;
SELECT student_id, date_first_registered, date_left FROM Students ORDER BY date_first_registered ASC LIMIT 1;
{ "sql": "SELECT DISTINCT S.SEMESTER_ID, S.SEMESTER_NAME, S.SEMESTER_DESCRIPTION, S.OTHER_DETAILS FROM Semesters S JOIN Students S2 ON S.SEMESTER_ID = S2.SEMESTER_ID JOIN Courses C ON S.COURSE_ID = C.COURSE_ID JOIN Departments D ON S.DEPARTMENT_ID = D.DEPARTMENT_ID JOIN Degree_Programs DP ON S.DEPARTMENT_ID = DP.DEPARTMENT_ID JOIN Student_Enrolment_Courses SC ON S.COURSE_ID = SC.COURSE_ID JOIN Courses C2 ON SC.COURSE_ID = C2.COURSE_ID JOIN Student_Enrolment C3 ON S.COURSE_ID = C3.COURSE_ID JOIN Student_Enrolment C4 ON C3.SEMESTER_ID = C4.SEMESTER_ID JOIN Student_Enrolment_Courses SC2 ON C4.COURSE_ID = SC2.COURSE_ID JOIN Student_Enrolment_Courses SC3 ON SC2.COURSE_ID = SC3.COURSE_ID JOIN Student_Enrolment_Courses SC4 ON SC3.COURSE_ID = SC4.COURSE_ID JOIN Student_Enrolment_Courses SC5 ON SC4.COURSE_ID = SC5.COURSE_ID JOIN Student_Enrolment_Courses SC6 ON SC5.COURSE_ID = SC6.COURSE_ID JOIN Student_Enrolment_Courses SC7 ON SC6.COURSE_ID = SC7.COURSE_ID JOIN Student_Enrolment_Courses SC8 ON SC7.COURSE_ID = SC8.COURSE_ID JOIN Student_Enrolment_Courses SC9 ON SC8.COURSE_ID = SC9.COURSE_ID JOIN Student_Enrolment_Courses SC10 ON SC9.COURSE_ID = SC10.COURSE_ID JOIN Student_Enrolment_Courses SC11 ON SC10.COURSE_ID = SC11.COURSE_ID JOIN Student_Enrolment_Courses SC12 ON SC11.COURSE_ID = SC12.COURSE_ID JOIN Student_Enrolment_Courses SC13 ON SC12.COURSE_ID = SC13.COURSE_ID JOIN Student_Enrolment_Courses SC14 ON SC13.COURSE_ID = SC14.COURSE_ID JOIN Student_Enrolment_Courses SC15 ON SC14.COURSE_ID = SC15.COURSE_ID JOIN Student_Enrolment_Courses SC16 ON SC15.COURSE_ID = SC16.COURSE_ID JOIN Student_Enrolment_Courses SC17 ON SC16.COURSE_ID = SC17.COURSE_ID JOIN Student_Enrolment_Courses SC18 ON SC17.COURSE_ID = SC18.COURSE_ID JOIN Student_Enrolment_Courses SC19 ON SC18.COURSE_ID = SC19.COURSE_ID JOIN Student_Enrolment_Courses SC20 ON SC19.COURSE_ID = SC20.COURSE_ID JOIN Student_Enrolment_Courses SC21 ON SC20.COURSE_ID = SC21.COURSE_ID JOIN Student_Enrolment_Courses SC22 ON SC21.COURSE_ID = SC22.COURSE_ID JOIN Student_Enrolment_Courses SC23 ON SC22.COURSE_ID = SC23.COURSE_ID JOIN Student_Enrolment_Courses SC24 ON SC23.COURSE_ID = SC24.COURSE_ID JOIN Student_Enrolment_Courses SC25 ON SC24.COURSE_ID = SC25.COURSE
SELECT S.student_id, D.department_id, D.department_name, D.department_description, D.degree_program_id, D.degree_summary_name, D.degree_summary_description FROM Departments D JOIN Degree_Programs DP ON D.department_id = DP.department_id JOIN Students S ON D.department_id = S.department_id JOIN Student_Enrolment_Courses SC ON S.student_id = SC.student_enrolment_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S2 ON C.course_id = S2.course_id JOIN Semesters S3 ON S2.semester_id = S3.semester_id WHERE D.department_id = DP.department_id AND D.department_name = DP.department_name AND D.degree_program_id = DP.degree_program_id AND D.degree_summary_name = DP.degree_summary_name AND D.degree_summary_description = DP.degree_summary_description;
SELECT COUNT(DISTINCT student_id) FROM Students;
SELECT Addresses.address_id, Addresses.line_1, Addresses.line_2, Addresses.line_3, Addresses.city, Addresses.zip_postcode, Addresses.state_province_county, Addresses.country, Addresses.other_address_details FROM Addresses JOIN Students ON Addresses.address_id = Students.current_address_id WHERE Students.first_name IS NOT NULL;
SELECT s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s ORDER BY s.last_name DESC;
SELECT s.first_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s ORDER BY s.first_name DESC LIMIT 10;
SELECT DISTINCT section_name, section_description FROM Sections;
SELECT section_description FROM Sections WHERE section_name = 'h'
