SELECT TV_Channel.id, TV_Channel.series_name, TV_Channel.Channel FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel JOIN Cartoon ON TV_series.Channel = Cartoon.Channel WHERE Cartoon.Title = 'The Rise of the Blue Beetle' AND Cartoon.Directed_by IS NULL;
SELECT TV_series.Title AS Animation_Name, TV_Channel.Series_name AS Series_Name FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_Channel.Series_name = 'Sky Radio'
