SELECT Episode, Rating, Share FROM TV_series ORDER BY Rating DESC LIMIT 3;
SELECT MAX(Pay_per_view_PPV) AS max_pay_per_view, MIN(Pay_per_view_PPV) AS min_pay_per_view FROM TV_series;
