SELECT TV_Channel.id, TV_Channel.Channel AS channel FROM TV_Channel JOIN TV_series ON TV_Channel.id = TV_series.Channel JOIN Cartoon ON TV_series.id = Cartoon.id WHERE Cartoon.Production_code = (SELECT Production_code FROM Cartoon ORDER BY Cartoon.Production_code DESC LIMIT 1)
SELECT TV_Channel.Package_Option, TV_Channel.series_name FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel WHERE TV_Channel.Pixel_aspect_ratio_PAR = 1.5 AND TV_Channel.Hight_definition_TV = 100;
